  "@canonical/summon-application/src/lib/Navigation/Navigation.tsx.ejs": "import { Link } from \"@canonical/router-react\";\nimport type { ReactElement } from \"react\";\nimport ThemeSelector from \"../ThemeSelector/index.js\";\n\nexport default function Navigation(): ReactElement {\n  return (\n    <nav aria-label=\"Main\">\n      <Link to=\"home\">Home</Link>\n      <Link params={{ slug: \"router-core\" }} to=\"guide\">\n        Guide\n      </Link>\n<% if (relay) { -%>\n      <Link to=\"catalog\">Catalog</Link>\n<% } -%>\n<% if (forms) { -%>\n      <Link to=\"contact\">Contact</Link>\n<% } -%>\n      <Link search={{ auth: \"1\" }} to=\"account\">\n        Demo sign-in\n      </Link>\n      <ThemeSelector />\n    </nav>\n  );\n}\n",
  "@canonical/summon-application/src/lib/Navigation/index.ts": "export { default } from \"./Navigation.js\";\n",
  "@canonical/summon-application/src/lib/ThemeSelector/ThemeSelector.tsx": "import { usePreferredTheme } from \"@canonical/react-hooks\";\nimport type { ChangeEvent, ReactElement } from \"react\";\n\nexport default function ThemeSelector(): ReactElement {\n  const { value, source, set, reset } = usePreferredTheme();\n\n  function handleChange(event: ChangeEvent<HTMLSelectElement>) {\n    const selected = event.target.value;\n\n    if (selected === \"system\") {\n      reset();\n    } else {\n      set(selected as \"light\" | \"dark\");\n    }\n  }\n\n  const selectValue = source === \"system\" ? \"system\" : value;\n\n  return (\n    <select\n      aria-label=\"Color theme\"\n      onChange={handleChange}\n      value={selectValue}\n    >\n      <option value=\"system\">System</option>\n      <option value=\"light\">Light</option>\n      <option value=\"dark\">Dark</option>\n    </select>\n  );\n}\n",
